mutants.old:
{sentences.length === 0 ? null : (
  <div
    data-testid="explanation"
    className="flex flex-col gap-2 rounded border border-border p-3 text-sm"
  >
    {sentences.map((sentence) => (
      <p key={sentence}>{sentence}</p>
    ))}
  </div>
)}
<Link
  to={`/research/stocks/${encodeURIComponent(evidence.symbol)}`}
  data-variant="outline"
  className={BUTTON}
>
  {SELECTION.seeEveryInput}
</Link>

mutants.new:
{canCompare ? (
  <Link
    to={`/research/compare?symbols=${checked.map(encodeURIComponent).join(",")}`}
    data-variant="outline"
    className={BUTTON}
  >
    {SELECTION.compareSideBySide}
  </Link>
) : (
  <>
    <button
      type="button"
      data-variant="blocked"
      aria-disabled="true"
      aria-describedby={reasonId}
      // Never `disabled`: a disabled control takes no focus, so its
      // reason would never reach a keyboard or screen-reader user. It
      // carries no handler, so activating it does nothing.
      className={BUTTON}
    >
      {SELECTION.compareSideBySide}
    </button>
    <span id={reasonId} className="text-sm">
      {SELECTION.compareBlocked}
    </span>
  </>
)}
<p aria-live="polite" className="text-sm">
  {SELECTION.selected(checked.length)}
</p>

{line === null ? null : (
  <dd data-testid="inputs-line" className="text-xs">
    {line}
  </dd>
)}
<dd>
  {cell === undefined ? (
    CELL.absentValue
  ) : (
    <FactorCell cell={cell} factor={factor} showScore />
  )}
</dd>
